ejemplos_codigo:
# try / except básico
try:
    resultado = 10 / 0
except ZeroDivisionError:
    print("Error: no se puede dividir entre cero")

# Capturar múltiples excepciones
def dividir(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return "Error: división entre cero"
    except TypeError:
        return "Error: los argumentos deben ser números"

print(dividir(10, 2))    # 5.0
print(dividir(10, 0))    # Error: división entre cero
print(dividir(10, "a"))  # Error: los argumentos deben ser números

# Obtener información del error
try:
    lista = [1, 2, 3]
    print(lista[10])
except IndexError as e:
    print(f"Error de índice: {e}")

# else y finally
def leer_numero():
    try:
        numero = int("42")
    except ValueError:
        print("No es un número válido")
    else:
        print(f"Número leído: {numero}")   # se ejecuta si no hay error
    finally:
        print("Intento de lectura finalizado")   # siempre se ejecuta

leer_numero()

# raise - lanzar excepciones propias
def validar_edad(edad):
    if not isinstance(edad, int):
        raise TypeError("La edad debe ser un número entero")
    if edad < 0 or edad > 150:
        raise ValueError(f"Edad inválida: {edad}")
    return True

try:
    validar_edad(200)
except ValueError as e:
    print(f"Valor inválido: {e}")

from functools import wraps
import time

# Decorador básico
def mayusculas(funcion):
    @wraps(funcion)
    def wrapper(*args, **kwargs):
        resultado = funcion(*args, **kwargs)
        return resultado.upper()
    return wrapper

@mayusculas
def saludar(nombre):
    return f"hola, {nombre}"

print(saludar("mundo"))   # HOLA, MUNDO

# Decorador para medir tiempo de ejecución
def medir_tiempo(funcion):
    @wraps(funcion)
    def wrapper(*args, **kwargs):
        inicio = time.perf_counter()
        resultado = funcion(*args, **kwargs)
        fin = time.perf_counter()
        print(f"{funcion.__name__} tardó {fin - inicio:.4f}s")
        return resultado
    return wrapper

@medir_tiempo
def suma_lenta(n):
    return sum(range(n))

total = suma_lenta(1_000_000)
print(f"Suma: {total}")

# Decorador con argumentos
def repetir(veces):
    def decorador(funcion):
        @wraps(funcion)
        def wrapper(*args, **kwargs):
            for _ in range(veces):
                resultado = funcion(*args, **kwargs)
            return resultado
        return wrapper
    return decorador

@repetir(3)
def decir(mensaje):
    print(mensaje)

decir("¡Hola!")   # imprime 3 veces

# Apilar decoradores
@medir_tiempo
@mayusculas
def obtener_saludo(nombre):
    return f"buenos días, {nombre}"

print(obtener_saludo("Ana"))

class Animal:
    def __init__(self, nombre, edad):
        self.nombre = nombre
        self.edad   = edad

    def respirar(self):
        print(f"{self.nombre} respira")

    def sonido(self):
        raise NotImplementedError("Cada animal debe implementar su sonido")

    def __str__(self):
        return f"{type(self).__name__}: {self.nombre} ({self.edad} años)"


class Perro(Animal):
    def __init__(self, nombre, edad, raza):
        super().__init__(nombre, edad)   # inicializa nombre y edad
        self.raza = raza

    def sonido(self):
        return "¡Guau guau!"

    def buscar(self, objeto):
        print(f"{self.nombre} va a buscar el {objeto}")


class Gato(Animal):
    def __init__(self, nombre, edad, indoor=True):
        super().__init__(nombre, edad)
        self.indoor = indoor

    def sonido(self):
        return "¡Miau!"

    def ronronear(self):
        print(f"{self.nombre} ronronea...")


class PajaroCantor(Animal):
    def sonido(self):
        return "¡Pío pío!"

    def cantar(self):
        print(f"{self.nombre} canta una melodía")


# Polimorfismo en acción
animales = [
    Perro("Rex", 3, "Labrador"),
    Gato("Luna", 5),
    PajaroCantor("Pío", 2),
    Perro("Toby", 7, "Beagle"),
]

for animal in animales:
    print(f"{animal.nombre}: {animal.sonido()}")

# isinstance
print(isinstance(animales[0], Perro))   # True
print(isinstance(animales[0], Animal))  # True
print(isinstance(animales[1], Perro))   # False

# issubclass
print(issubclass(Perro, Animal))        # True

# @property - la forma más común de usar descriptores
class Temperatura:
    def __init__(self, celsius=0):
        self._celsius = celsius

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, valor):
        if valor < -273.15:
            raise ValueError("Temperatura por debajo del cero absoluto")
        self._celsius = valor

    @property
    def fahrenheit(self):
        return self._celsius * 9/5 + 32

    @property
    def kelvin(self):
        return self._celsius + 273.15

t = Temperatura(25)
print(f"{t.celsius}°C = {t.fahrenheit}°F = {t.kelvin}K")
t.celsius = 100
print(f"Agua hirviendo: {t.fahrenheit}°F")

# Descriptor personalizado
class Positivo:
    """Descriptor que solo acepta valores positivos"""
    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return getattr(obj, f"_{self.name}", None)

    def __set__(self, obj, value):
        if value <= 0:
            raise ValueError(f"{self.name} debe ser positivo, got {value}")
        setattr(obj, f"_{self.name}", value)

class Rectangulo:
    ancho  = Positivo()
    alto   = Positivo()

    def __init__(self, ancho, alto):
        self.ancho = ancho
        self.alto  = alto

    @property
    def area(self):
        return self.ancho * self.alto

r = Rectangulo(5, 3)
print(f"Área: {r.area}")   # 15

try:
    r.ancho = -1
except ValueError as e:
    print(e)   # ancho debe ser positivo, got -1

from typing import Optional, Union, Callable, TypeVar
from collections.abc import Sequence

# Anotaciones básicas
def saludar(nombre: str, veces: int = 1) -> str:
    return (f"¡Hola, {nombre}! " * veces).strip()

print(saludar("Ana"))
print(saludar("Luis", 3))

# Tipos compuestos (Python 3.10+ usa | para Union)
def procesar(valor: int | str) -> str:
    if isinstance(valor, int):
        return f"Número: {valor}"
    return f"Texto: {valor}"

# Optional (puede ser None)
def buscar_usuario(id: int) -> Optional[dict]:
    usuarios = {1: {"nombre": "Ana"}, 2: {"nombre": "Luis"}}
    return usuarios.get(id)   # puede devolver None

usuario = buscar_usuario(1)
if usuario:
    print(usuario["nombre"])

# Tipos de colecciones
def sumar_lista(numeros: list[int]) -> int:
    return sum(numeros)

def contar_palabras(texto: str) -> dict[str, int]:
    conteo: dict[str, int] = {}
    for palabra in texto.split():
        conteo[palabra] = conteo.get(palabra, 0) + 1
    return conteo

# TypeVar - función genérica
T = TypeVar('T')

def primero(secuencia: Sequence[T]) -> T | None:
    return secuencia[0] if secuencia else None

print(primero([1, 2, 3]))       # int
print(primero(["a", "b"]))      # str
print(primero([]))              # None

# Callable
def aplicar(funcion: Callable[[int], int], valor: int) -> int:
    return funcion(valor)

print(aplicar(lambda x: x ** 2, 5))   # 25

# archivo: calculadora.py
def sumar(a, b):
    return a + b

def dividir(a, b):
    if b == 0:
        raise ZeroDivisionError("No se puede dividir entre cero")
    return a / b

def es_primo(n):
    if n < 2:
        return False
    return all(n % i != 0 for i in range(2, int(n**0.5) + 1))


# archivo: test_calculadora.py
import pytest
# from calculadora import sumar, dividir, es_primo

# Test básico
def test_sumar():
    assert sumar(2, 3) == 5
    assert sumar(-1, 1) == 0
    assert sumar(0, 0) == 0

# Test de excepción
def test_dividir_entre_cero():
    with pytest.raises(ZeroDivisionError, match="No se puede dividir"):
        dividir(10, 0)

def test_dividir():
    assert dividir(10, 2) == 5.0
    assert dividir(7, 2) == 3.5

# Parametrize - mismo test con varios datos
@pytest.mark.parametrize("numero, esperado", [
    (2,  True),
    (3,  True),
    (4,  False),
    (17, True),
    (18, False),
    (97, True),
    (1,  False),
    (0,  False),
])
def test_es_primo(numero, esperado):
    assert es_primo(numero) == esperado

# Fixture
@pytest.fixture
def lista_numeros():
    return [5, 2, 8, 1, 9, 3, 7, 4, 6]

def test_suma_lista(lista_numeros):
    assert sum(lista_numeros) == 45

def test_maximo(lista_numeros):
    assert max(lista_numeros) == 9

# Ejecutar: pytest test_calculadora.py -v
